from collections import Counter

class Solution:
    def maxOperations(self, nums: list[int], k: int) -> int:
        count = Counter(nums)
        result = 0
        for num in count:
            comp = k - num
            if comp == num:
                result += count[num] // 2
            elif comp in count and comp > num:
                result += min(count[num], count[comp])
        return result

